  target.querySelector('#classProgramForm')?.addEventListener('submit',event=>{event.preventDefault();adultAction(async()=>{const form=new FormData(event.currentTarget),units=[...target.querySelectorAll('[data-program-unit]')].filter(node=>node.value).map(node=>({id:node.dataset.programUnit,status:node.value}));await account.request('class-program-save',{club:managedClub,schoolYear:form.get('schoolYear').trim(),title:form.get('title').trim(),teacherLabel:form.get('teacherLabel').trim(),method:form.get('method').trim(),examGoal:form.get('examGoal').trim(),units,expectedRevision:form.get('schoolYear').trim()===program.schoolYear?(Number(program.editVersion)||0):0});return 'Bozza salvata. Gli esercizi pubblicati restano quelli della versione precedente fino alla conferma.';});});
  target.querySelector('#classProgramPublishReview')?.addEventListener('click',()=>{const panel=target.querySelector('#classProgramPublishPanel'),saved=program.units||[];panel.innerHTML='<section class="programReview"><h4>Pubblica la bozza salvata</h4><p>'+esc(program.title)+' · '+esc(program.schoolYear)+'</p><ul>'+saved.map(unit=>'<li>'+esc(units.find(row=>row.id===unit.id)?.title||unit.id)+': '+esc({active:'In allenamento',review:'Da ripassare',planned:'Pianificato'}[unit.status])+'</li>').join('')+'</ul><p>Le modifiche non ancora salvate nel modulo non verranno pubblicate. Gli esercizi già iniziati conserveranno la loro versione.</p><label class="programCheck"><input type="checkbox" id="classProgramPublishChecked">Ho rivisto la bozza e confermo gli argomenti della classe.</label><button class="primary" id="classProgramPublishConfirm" type="button" disabled>Pubblica programma</button><button class="audio" id="classProgramPublishCancel" type="button">Annulla</button></section>';panel.querySelector('#classProgramPublishChecked').onchange=event=>panel.querySelector('#classProgramPublishConfirm').disabled=!event.target.checked;panel.querySelector('#classProgramPublishCancel').onclick=()=>panel.replaceChildren();panel.querySelector('#classProgramPublishConfirm').onclick=()=>adultAction(async()=>{await account.request('class-program-publish',{program:program.id,expectedRevision:program.editVersion,confirmed:true});await refresh();return 'Programma pubblicato. I nuovi esercizi usano la versione confermata.';});});
  bindForm(target,'#classProgramMaterialForm',async form=>{const lines=form.get('words').split(/\r?\n/).map(line=>line.trim()).filter(Boolean);if(!lines.length||lines.length>80)throw Error('Inserisci da 1 a 80 parole, una per riga.');const words=lines.map(line=>{const parts=line.split('|').map(value=>value.trim());if(parts.length<2||parts.length>3||!parts[0]||!parts[1])throw Error('Usa parola inglese | significato italiano | simbolo facoltativo, una riga per parola.');return [parts[0],parts[1],parts[2]||'📖'];});await account.request('class-program-material-save',{club:managedClub,title:form.get('title').trim(),words,confirmed:true});return 'Materiale rivisto salvato nella classe. Puoi assegnarlo alla bozza prima di pubblicare.';});
