  const consentSelect=target.querySelector('#classProgramConsentProfile');if(consentSelect){const update=()=>{const choice=(data.consentTargets||[]).find(item=>Number(item.profile)===Number(consentSelect.value)&&Number(item.club)===Number(consentSelect.selectedOptions[0]?.dataset.club));target.querySelector('#classProgramConsentAllowed').checked=choice?.allowed===true;target.querySelector('#classProgramConsentConfirm').checked=false;};consentSelect.addEventListener('change',update);update();}
